{"command": "python - <<'EOF'
from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.adjustments import refund
from ledgerly.errors import BillingError

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(status="captured"):
    return Payment("p","i",Decimal("100.00"),status=status,created_at=T0,captured_at=T0)

p=mk(); refund(p,Decimal("40"),T0); refund(p,Decimal("60"),T0)
assert p.refunded_amount==Decimal("100.00") and p.status=="refunded", p
print("full cumulative ok", p)

p=mk()
try: refund(p,Decimal("100.01"),T0)
except BillingError as e: print("over:", e.code)
assert p.refunded_amount==Decimal("0.00")

for st in ("authorized","voided","refunded"):
    try: refund(mk(st),Decimal("1"),T0)
    except BillingError as e: print(st, "->", e.code)

for amt in (Decimal("0"), Decimal("-1")):
    try: refund(mk(),amt,T0)
    except BillingError as e: print("amt",amt,"->",e.code)

try: refund(mk(),Decimal("1"),datetime(2026,1,1))
except BillingError as e: print("naive ->", e.code)
print("all edge cases ok")
EOF"}

